package tv.vela.launcher;

import org.json.*;
import java.util.*;

public final class CatalogFiltersTest {
    private static int checks;
    private static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    public static void main(String[] args)throws Exception{
        PlexClient.Section movies=new PlexClient.Section("1","Movies","movie"),shows=new PlexClient.Section("2","Series","show");CatalogFilters.Query q=new CatalogFilters.Query();
        String path=CatalogFilters.plexPath(movies,24,q);check(path.contains("type=1")&&path.contains("addedAt%3Adesc%2CtitleSort%3Aasc")&&path.contains("Start=24")&&path.endsWith("Size=24"),"default Plex recent ordering or page scope lost");check(CatalogFilters.plexPath(shows,0,q).contains("type=2"),"series query mixed with movies");
        check(CatalogFilters.jellyfinQuery(q).contains("sortBy=DateCreated,SortName")&&CatalogFilters.jellyfinQuery(q).contains("sortOrder=Descending,Ascending"),"Jellyfin default recent and stable tie order lost");
        CatalogFilters.Facet genre=CatalogFilters.fixed("genre","Genre",true,"1","2"),year=CatalogFilters.fixed("year","Year",true,"2020");q.toggle(genre,new CatalogFilters.Choice("1","Acción"));q.toggle(genre,new CatalogFilters.Choice("2","Drama"));q.toggle(year,new CatalogFilters.Choice("2020","2020"));q.search="El señor & la luna";
        path=CatalogFilters.plexPath(movies,0,q);check(path.contains("genre=1%2C2")&&path.contains("year=2020")&&path.contains("title=El+se%C3%B1or+%26+la+luna"),"combined filters or encoded text corrupted");CatalogFilters.Query clone=q.copy();clone.toggle(genre,new CatalogFilters.Choice("1","Acción"));check(q.selected("genre","1")&&!clone.selected("genre","1"),"in-flight query changed after editing draft");
        JSONObject details=new JSONObject("{\"MediaContainer\":{\"Meta\":{\"Type\":[{\"type\":\"movie\",\"Sort\":[{\"key\":\"titleSort\",\"title\":\"Title\"},{\"key\":\"random\",\"title\":\"Random\"}],\"Filter\":[{\"filter\":\"genre\",\"title\":\"Genre\",\"key\":\"/library/sections/1/genre?type=1\"},{\"filter\":\"actor\",\"key\":\"https://other.invalid/actors\"},{\"filter\":\"country\",\"key\":\"/library/sections/2/country\"}]}]}}}");CatalogFilters.Options opts=CatalogFilters.plexOptions(details,movies);check(opts.facets.size()==2&&opts.facets.get(1).id.equals("genre"),"foreign or mismatched server filter route accepted");check(opts.sorts.size()==2&&opts.sorts.get(0).key.equals("addedAt"),"native sorts or recent default missing");
        check(CatalogFilters.safePlexFacet("genre?type=1",movies).equals("/library/sections/1/genre?type=1"),"relative native facet key not resolved inside its section");
        for(String bad:new String[]{"https://other.invalid/x","//other.invalid/x","/library/sections/1/../2/genre","/library/sections/1/%2e%2e","/library/sections/1/genre?token=bad","/library/sections/1/genre#x"})check(CatalogFilters.safePlexFacet(bad,movies).isEmpty(),"unsafe facet URL accepted");
        JSONArray terms=new JSONArray();for(int i=0;i<80;i++)terms.put(new JSONObject().put("key",String.valueOf(i)).put("title","Genre "+i));JSONObject all=new JSONObject().put("MediaContainer",new JSONObject().put("Directory",terms));CatalogFilters.Choices first=CatalogFilters.plexChoices(all,0,"");CatalogFilters.Choices second=CatalogFilters.plexChoices(all,24,"");check(first.items.size()==24&&first.nextOffset()==24&&second.items.get(0).value.equals("24"),"unpaginated Plex choices not bounded/sliced");check(CatalogFilters.plexChoices(all,0,"Genre 79").items.size()==1,"choice search lost");
        JSONObject remote=new JSONObject().put("MediaContainer",new JSONObject().put("Directory",new JSONArray().put(new JSONObject().put("key","50").put("title","Drama"))).put("offset",24).put("totalSize",100));check(CatalogFilters.plexChoices(remote,24,"").nextOffset()==25,"server choice offset lost");
        CatalogFilters.Options jf=CatalogFilters.jellyfinOptions(new JSONObject().put("Years",new JSONArray().put(2020).put(2025)).put("OfficialRatings",new JSONArray().put("PG-13")),new JSONObject().put("Genres",new JSONArray().put(new JSONObject().put("Id","11111111111111111111111111111111").put("Name","Drama"))).put("Tags",new JSONArray().put("cine")),movies);check(jf.facets.stream().anyMatch(f->f.id.equals("genreIds"))&&jf.facets.stream().anyMatch(f->f.id.equals("years")),"Jellyfin server facets missing");
        CatalogFilters.Options legacy=CatalogFilters.jellyfinOptions(new JSONObject().put("Genres",new JSONArray().put("Action").put("Drama")),new JSONObject().put("Genres",new JSONArray()),movies);check(legacy.facets.stream().anyMatch(f->f.id.equals("genres")&&f.fixed.size()==2),"name-based genre fallback missing");
        CatalogFilters.Query jq=new CatalogFilters.Query();jq.toggle(CatalogFilters.fixed("tags","Tags",true,"cine"),new CatalogFilters.Choice("cine","cine"));jq.toggle(CatalogFilters.fixed("isFavorite","Favorites",false,"true"),new CatalogFilters.Choice("true","true"));jq.toggle(CatalogFilters.fixed("$state","Status",false,"unwatched"),new CatalogFilters.Choice("unwatched","unwatched"));check(CatalogFilters.jellyfinQuery(jq).contains("tags=cine")&&CatalogFilters.jellyfinQuery(jq).contains("isFavorite=true")&&CatalogFilters.jellyfinQuery(jq).contains("isPlayed=false"),"combined Jellyfin filters missing");
        for(String bad:new String[]{"sort","SORT","userId","ParentId","parentId","X-Plex-Token","title&token","../actor"})check(!CatalogFilters.field(bad),"reserved field accepted");
        CatalogFilters.Query invalid=new CatalogFilters.Query();invalid.sort="random";boolean refused=false;try{CatalogFilters.plexPath(movies,0,invalid);}catch(Exception expected){refused=true;}check(refused,"random paging order accepted");invalid=new CatalogFilters.Query();invalid.values.put("parentId",Collections.singletonList(new CatalogFilters.Choice("bad","bad")));refused=false;try{CatalogFilters.jellyfinQuery(invalid);}catch(Exception expected){refused=true;}check(refused,"filter escaped selected library");
        System.out.println("PASS "+checks+" server catalog filter, query, scope, ordering, encoding and bounded option checks");
    }
}
